import { isUndefined } from 'lodash-es';

import { DEFAULT_MARKER_COLOR } from '../../annotations-atoms/constants.js';
import { AnnotationData } from '../types/annotations.js';

/**
 * Define the main color of the marker:
 *    No Colors = Default Color
 *    Priority matching color = Lowest Priority Color
 *    Priority not matching color = First color found
 *
 * @param annotations -
 * @returns color(string)
 */
export function defineMarkerColor(annotations: AnnotationData[]): string {
  const annotationsHaveNoColor = annotations.every((annotation) =>
    isUndefined(annotation.color),
  );
  const priorityColorTuples = annotations.filter(
    (annotation) =>
      !isUndefined(annotation.priority) && !isUndefined(annotation.color),
  );

  if (annotationsHaveNoColor) {
    return DEFAULT_MARKER_COLOR;
  }
  if (!annotationsHaveNoColor && priorityColorTuples.length === 0) {
    return annotations.find((annotation) => !isUndefined(annotation.color))!
      .color!;
  }

  const priorities = priorityColorTuples
    .map((data) => data.priority)
    .filter((p) => !isUndefined(p)) as number[];

  const minPriority = Math.min(...priorities);
  const minPriorityIndex = priorityColorTuples.findIndex(
    (data) => data.priority === minPriority,
  );

  return priorityColorTuples[minPriorityIndex].color!;
}
